.section {
  position: relative;
  width: 100%;
  min-height: calc(100vh - 150px);
  overflow: hidden;
  padding: 1em 5%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.section .content {
  width: 100%;
}
.oval {
  position: absolute;
  top: -50px;
  height: 500px;
}
.oval svg {
  height: 100%;
}
.oval-left {
  left: 0;
}
.oval-right {
  right: 0;
}

footer {
  margin-top: 50px;
  color: white;
  height: 100px;
  text-align: center;
}
footer span {
  color: red;
}

.terminal-footer {
  height: 50px;
  /* position: absolute;
  bottom: 0;
  left: 0; */
  padding: 0 40px;
  margin-top: 50px;
  z-index: 99;
}
.terminal-footer rect,
.terminal-footer path {
  fill: var(--footer-color);
  stroke: var(--footer-color);
}

.section {
  animation: fade-in 0.3s ease-in;
}

@keyframes fade-in {
  0% {
    opacity: 0;
  }
  100% {
